theorem mathd_numbertheory_709 (n : ℕ) (h₀ : 0 < n) (h₁ : Finset.card (Nat.divisors (2 * n)) = 28)
  (h₂ : Finset.card (Nat.divisors (3 * n)) = 30) : Finset.card (Nat.divisors (6 * n)) = 35 := by
  have h_main : n = 864 := by
    have h₃ : n = 864 := by
      -- We use the given conditions to find the value of n
      have h₄ : n = 864 := by
        -- We use the given conditions to find the value of n
        rw [Nat.divisors_mul, Nat.divisors_mul] at h₁ h₂
        -- Simplify the conditions using the given conditions
        <;>
        (try norm_num at h₁ h₂) <;>
        (try
          {
            rcases n with (_ | _ | _ | _ | _ | _ | _ | _ | _ | _ | _ | _ | _ | _ | _ | _ | _ | n) <;>
            norm_num [Nat.divisors_prime_pow, Nat.divisors_mul, Nat.prime_two, Nat.prime_three] at h₁ h₂ <;>
            (try omega) <;>
            (try
              {
                ring_nf at h₁ h₂ ⊢
                omega
              }
            )
          }
        ) <;>
        (try omega) <;>
        (try
          {
            aesop
          }
        ) <;>
        (try
          {
            simp_all (config := {decide := true})
            <;>
            omega
          }
        ) <;>
        (try
          {
            nlinarith
          }
        ) <;>
        (try
          {
            aesop
          }
        ) <;>
        (try
          {
            omega
          }
        ) <;>
        (try
          {
            nlinarith
          }
        )
        <;>
        omega
      exact h₄
    exact h₃

  have h_final : Finset.card (Nat.divisors (6 * n)) = 35 := by
    rw [h_main]
    apply Eq.symm
    rfl

  apply h_final

import Mathlib
import Aesop

